pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small
    // "dead zones" (1..=9) are nearly useless, penalize creating them.
    let pr = post_residual.min(bin_capacity);
    let dead_zone = pr > 0 && pr <= 9;
    if dead_zone {
        score += 40.0;
    }

    // Modulo-10 class: residuals that are multiples of 10 pair well with
    // typical item sizes; reward them.
    if pr % 10 == 0 {
        score -= 8.0;
    } else if pr % 5 == 0 {
        score -= 4.0;
    }

    // Exact fit is ideal.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly
    // favor this bin (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            let chain_residual = pr - next_item_size;
            if chain_residual % 10 == 0 {
                score -= 12.0;
            }
            if chain_residual <= 9 {
                score += 15.0;
            }
        } else {
            // next item won't fit here; slight penalty for tight packing that
            // strands the lookahead.
            score += 3.0;
        }
    }

    // Integer-division threshold: keep residual above half capacity when
    // possible (flexibility for large items).
    if pr > bin_capacity / 2 {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when the item is
    // large or many bins are already open; otherwise discourage.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 - 10.0 * item_frac - 5.0 * progress
            - 2.0 * open_bins_count as f64
            + if fitting_bins_count > 0 { 30.0 } else { 0.0 };
        if dead_zone {
            score -= 5.0; // fresh bin avoids dead-zone creation
        }
    }

    // Mean residual coupling: prefer bins below the mean residual (tighter bins),
    // saving roomier bins for future items.
    score -= 0.15 * (mean_residual - post_residual as f64);

    score
}

