    let mut score = post_residual as f64;

    // Strong reward for near-exact fit (waste minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits: bonus proportional to tightness of that second fit
            let second_residual = post_residual - next_item_size;
            score -= 120.0 - (second_residual as f64) * 2.0;
        } else {
            // next item does NOT fit this bin after placement: penalize
            // more severely if the leftover dead space is small and unusable
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 150.0;
            } else {
                score += 40.0;
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far above mean are
    // "loose" bins; prefer packing into them to consolidate open bins.
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.8;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Prefer consolidating into fewer bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 5.0;

    // New-bin candidate: only attractive when item fits poorly everywhere.
    // Penalize opening a new bin unless residual would be large and useful.
    if bin_residual == bin_capacity {
        score = (post_residual as f64) + 300.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
        if fitting_bins_count == 1 {
            score += 400.0; // never open new bin when a last-chance bin exists
        }
    }

    score
}

