pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: match post_residual against next_item_size.
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 1.5
        };
        // Reward exact 2-step matches strongly.
        score -= 40.0 * (-gap / 12.0).exp();
        // Penalize leaving residual just below next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
        // Bonus if next item exactly fills the bin after this placement.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: pure tightness.
        score -= 10.0;
    }

    // Relative-to-mean-residual coupling: bins with residual far from mean
    // that end up close to mean are attractive consolidation targets.
    let new_gap = (post_residual as f64 - mean_residual).abs();
    let old_gap = (bin_residual as f64 - mean_residual).abs();
    score -= 3.0 * (old_gap - new_gap).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize near-full bins slightly less than wasteful large residuals
    // when many bins are open (encourage consolidation).
    if open_bins_count > 3 {
        score -= 0.05 * (bin_capacity as f64 - post_residual as f64);
    }

    // New-bin candidate: prefer it only when nothing fits well.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 6.0; // discourage opening when lookahead could chain
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual (tight fit preferred)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: tolerate moderate residuals (bins get reused later).
    // Late stream: strongly prefer tight fits since fewer chances remain.
    let tightness = norm_pr * norm_pr * norm_pr; // cubic dead-space penalty
    score += tightness * cap * (0.5 + 1.5 * progress);

    // Smooth interaction: reward filling bins whose residual matches the lookahead item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 4.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
        // Penalize leaving residual slightly above next item (wasted sliver)
        score += 6.0 * (1.0 - (gap / cap).min(1.0)) * progress;
    }

    // Last-chance bonus: only one bin fits -> strong reward for using it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Mild pressure toward consolidating into fewer bins as stream progresses.
    score += 0.3 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins with residual below mean (use up the emptier bins first).
    score += 2.0 * (mean_residual - pr) / cap;

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && norm_pr < 0.0; // never true for new bin
        let _ = good_fit_exists;
        // Smooth gate: open new bin when current bins have large residuals late in stream,
        // otherwise penalize opening bins.
        let openness = (mean_residual / cap).powi(2) * progress;
        score = cap - 20.0 * openness + 8.0 * (1.0 - progress);
    }

    score
}

