        score += 0.3 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early (many bins to spread load)
        // and when the item leaves a clean large residual that matches the next item.
        let early_bonus = (1.0 - progress) * 6.0;
        let chain_bonus = if next_item_size > 0 && post_residual >= next_item_size { 3.0 } else { 0.0 };
        score -= early_bonus + chain_bonus;

        // Penalize opening new bins when plenty of open bins already fit the item
        score += 2.0 * fitting_bins_count as f64;

        // Late in the stream, prefer consolidation: opening new bins is costly
        score += 10.0 * progress;
    }

    // Global pressure: when mean residual across open bins is small (bins nearly full),
    // encourage using existing bins rather than fragmenting
    let mean_pressure = 1.0 - (mean_residual / (bin_capacity as f64)).clamp(0.0, 1.0);
    score -= 3.0 * mean_pressure * (1.0 - tightness);

    // Penalize selecting bins far from the mean residual (fragmentation of bin states)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Mild preference to keep number of open bins low when many bins are open
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count as f64 - 4.0) * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer minimal post residual (best fit)
    let mut score = pr;

    // Smooth normalized post-residual polynomial: penalize awkward mid-range residuals
    let x = pr / cap;
    score += 12.0 * x * (1.0 - x) * (x - 0.5) * (x - 0.5) * 4.0;

    // Tight-fit reward: smooth quadratic in item fraction
    let f = it / cap;
    score -= 20.0 * f * (1.0 - f) * (1.0 - x);

    // Stream-progress coupling: later in the stream, reward tight packing more strongly
    score -= progress * 10.0 * (1.0 - x) * (1.0 - x);

    // Dead-space aversion grows with progress (non-linear)
    score += progress * progress * pr * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: prefer it only when it enables a better future fit
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let room_for_next = if next_item_size > 0 { (cap - next_item_size as f64).max(0.0) } else { 0.0 };
        // Penalize new bin unless leftover space can hold the next item
        score += 8.0 + 0.5 * open_bins_count as f64 - 0.2 * room_for_next * (1.0 - progress);
    } else {
        // Reward bins whose residual pairs with the lookahead item
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 6.0 * (pr / cap);
        }
        // Slight penalty for very large residuals relative to mean (wasteful bins)
        score += 0.1 * (pr - mean_residual).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Residuals divisible by 10 align with the item-size lattice -> highly reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: enormous reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual (mod arithmetic on capacity fractions).
    if post_residual % 10 == 0 {
        score -= 8.0; // lattice-aligned leftover, likely reusable
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        score += 4.0; // awkward off-lattice dead space
    }

    // Small leftovers are the worst: penalize via inverse-square dead-space term.
    if post_residual > 0 {
        score += 400.0 / pr;
    }

    // Integer-division thresholds: classify leftover into size classes.
    let class = post_residual / 20; // 0..5 classes
    score += match class {
        0 => 25.0,               // tiny unusable sliver
        1 => 8.0,
        2 => 0.0,
        3 => -4.0,
        _ => -6.0,               // roomy leftover
    };

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // chains the next item into this bin
            if next_item_size == post_residual {
                score -= 20.0; // exact chain: both items fill bin perfectly
            }
        } else if next_item_size <= bin_residual {
            score += 6.0; // we consumed space the next item could have used
        }
        // Harmonic check: next item aligns with leftover lattice
        if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline score.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early (many items left) or when
        // open bins are all poorly filled (high mean residual = bad fits).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 40.0 * progress;
        // If open bins are wasteful (mean residual large), new bin less bad.
        score -= (mean_residual / cap) * 10.0;
        // Crowding: many open bins -> prefer consolidating into existing ones.
        score += open_bins_count as f64 * 2.0;
        // A brand-new bin still has full residual; keep the harmonic terms neutral.
        return score;
    }

    // Mild preference for fuller bins when many bins are open (consolidation).
    score -= (1.0 - bin_residual as f64 / cap) * (open_bins_count as f64);

    // Late-stream tightening: as the stream ends, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * (0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever be useful are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 0.0; // perfect fit
    } else {
        // Gap smaller than the smallest conceivable item -> dead space.
        if post_residual < 10 {
            score += 40.0;
        }
        // Gap that cannot fit the lookahead item is less valuable.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward filling a bin deeply relative to capacity.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize slightly so it is chosen only when open bins are bad fits,
    // with pressure decreasing as open-bin count grows (consolidate when many bins open).
    if bin_residual == bin_capacity {
        let pressure = 20.0 / (1.0 + open_bins_count as f64 * 0.15);
        score += pressure;
        // Opening a new bin is more attractive early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
    }

    // Mild penalty for bins far from the mean residual (prefer typical bins, avoid outlier waste).
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
