pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits: squared residual gap penalty
    score += 0.8 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0;

    // Lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; small penalty proportional to wasted potential
        score += 5.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins have plenty of room
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = mean_residual / bin_capacity as f64;
        score += 30.0 + 50.0 * pressure * (1.0 - progress);
        // early stream: slightly prefer consolidating
        score += 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    } else {
        // Reward using bins with residual below mean (consolidation)
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Prefer filling bins that are already mostly full
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 15.0 * fill * fill;

    // Penalize leaving dead space that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 20 {
        score += 3.0; // awkward small residual
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on wasted space (post_residual)
    let mut score = post * (1.0 + norm_post);

    // Smooth coupling: tight fits are progressively more rewarded as stream advances
    let tightness = 1.0 - norm_post;
    score -= cap * (tightness * tightness) * (0.5 + progress);

    // Penalize very small dead space less early (usable later), more late
    let dead = (norm_post - 0.2).max(0.0);
    score += cap * dead * dead * (1.0 + 2.0 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= cap * (0.6 + 0.4 * progress);
    }

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_next = norm_post - nx;
        if fit_next >= 0.0 {
            score -= cap * 0.5 * (1.0 - (fit_next - nx).abs()) * (1.0 - progress * 0.5);
        } else {
            score += cap * 0.3 * (-fit_next);
        }
    }

    // Mild pressure to consolidate when many bins are open relative to mean residual
    score += open_bins_count as f64 * norm_post * 0.1;

    // Prefer bins with residual near/below mean (consolidation tendency), smooth term
    score += 0.2 * (post - mean_residual) * norm_item;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (low post residual), with a floor to avoid
    // over-rewarding degenerate zero-residual placements.
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Leftovers that fall into "harmonic" classes
    // (cap/4, cap/2, etc.) are reusable by typical items; odd tiny leftovers
    // are dead space and get penalized.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let dead_zone = bin_capacity / 10; // leftovers < 10% capacity are near-useless

    if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 60.0;
    } else if post_residual < dead_zone {
        // Tiny dead space: penalize proportionally.
        score += (dead_zone - post_residual) as f64 * 2.0;
    } else if post_residual <= quarter {
        // Small but plausibly usable class: mild penalty.
        score += 5.0;
    } else if post_residual <= half {
        // Half-class: usable by many items, mild reward.
        score -= 3.0;
    } else {
        // Large leftover: still roomy, fine.
        score -= 1.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic residue class via integer division: how many times
            // could the next item stack into the leftover?
            let stacks = post_residual / next_item_size.max(1);
            score -= 12.0 + 4.0 * stacks.min(3) as f64;
        } else {
            // Next item won't fit here: this placement "burns" the bin's
            // future usefulness; penalize by the mismatch gap.
            let gap = next_item_size - post_residual;
            score += gap.min(bin_capacity) as f64 * 0.5;
        }
    }

    // Last-chance logic: if this is the only bin that fits the item, strongly
    // prefer it over opening a new bin (unless the new bin call scores lower).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate guard: an empty bin should only win when the current
    // bin's fit is genuinely bad. Penalize opening a new bin when a decent
    // fit exists (post_residual small relative to capacity).
    if bin_residual == bin_capacity {
        // Slight bias against new bins; scaled by stream progression so early
        // stream is a bit more willing to open bins (exploration), late stream
        // is conservative (packing density matters more).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 8.0 + 10.0 * progress;
        // If open bins are already crowded (low mean residual), new bin is fine.
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 6.0;
    }

    // Prefer packing into bins with residual close to the item (tightness
    // refinement): reward small bin_residual - item_size gap beyond post_residual.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    // Mild pressure to keep open bin count manageable.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (too small for the smallest plausible item)
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 1000.0; // perfect fill
    } else {
        // penalize small unusable gaps much harder than large reusable residuals
        let dead = post_residual as f64;
        let deadness = if dead < 20.0 {
            3.0 - dead / 20.0 // up to 3x penalty for tiny gaps
        } else {
            1.0
        };
        score += dead * (deadness - 1.0) * 2.0;
    }

    // Reward tight fits (post_residual close to zero relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin unless it enables a great future fit
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let lookahead_bonus = if next_item_size > 0 && (next_item_size as f64) <= bin_residual as f64 {
            10.0
        } else {
            0.0
        };
        score += 60.0 + open_bins_count as f64 * 4.0 - progress * 10.0 - lookahead_bonus;
    }

    // Open-bin pressure: mild penalty scaling with number of open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // next item won't fit here anyway; slight penalty for stranding residual
        score += 5.0;
    }

    // Mean-residual coupling: prefer bins near the mean (keeps residual distribution balanced)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: squashed post-residual dominates.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness * tightness;

    // 2-step lookahead: if next item fits into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here: mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.35 * over;
        }
    }

    // Compare post_residual to mean residual: leaving less than average is good.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    // (large post_residual waste potential otherwise).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty for opening a new bin; shrinks if current bin would leave tiny dead space.
        let dead = post_residual as f64;
        score += 70.0 - 0.9 * dead + 20.0 * progress;
    }

    // Mild preference for filling fuller bins among many open bins.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: square the post-residual to strongly prefer snug placements.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual < next_item_size {
            // Dead space relative to the next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // If next item fits comfortably in leftover, mild reward.
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are fragmented (high mean residual spread) or few bins fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize new bins more when open bins are relatively empty and numerous.
        score += 40.0
            - fragmentation * 30.0
            - (fitting_bins_count == 0) as i32 as f64 * 100.0
            + progress * 10.0;
    } else {
        // Prefer filling already-open bins with large residual (reduce fragmentation).
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 15.0;

        // Mild penalty for spreading across many open bins when mean residual is low.
        if (item_size as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - item_size as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = pr / cap;

    // Base: post residual, mildly warped by a smooth polynomial of fill fraction.
    let mut score = pr * (1.0 + 0.6 * fit_ratio * (1.0 - fit_ratio) * 4.0);

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are increasingly rewarded.
    let tightness = (cap - pr) / cap; // fraction filled after placement
    score -= 30.0 * progress * tightness * tightness;

    // Penalize dead space quadratically, scaled by progress.
    score += 0.35 * fit_ratio * fit_ratio * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (pr - nxt) / cap;
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Prefer bins deviating below mean residual (keep a spread of sizes).
    score += 0.15 * ((pr - mean_residual) / cap);

    // Mild penalty for accumulating many open bins late in the stream.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by residue mod 20 (capacity/5)
    let residue_class = (post_residual % 20) as f64;
    let harmonic_bucket = (post_residual / 20) as f64;

    // Penalize post-residuals that are not "nice" fractions of capacity.
    // Nice residuals: 0 (perfect fit), or multiples of 20 (quarter capacity).
    if post_residual == 0 {
        score -= 100.0; // perfect fit: strongly reward
    } else if post_residual % 20 == 0 {
        score -= 10.0; // clean fraction of capacity
    } else {
        score += residue_class * 0.5; // dead-space penalty scaled by residue
    }

    // Integer-division thresholds on post_residual: small leftovers are risky
    if post_residual <= 10 {
        score += 25.0; // nearly unusable sliver
    } else if post_residual > 40 {
        score -= 5.0; // roomy residual is flexible
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: reward when next item lands on a compatible class
            let pair_residue = ((post_residual - next_item_size) % 20) as f64;
            score -= 15.0 - pair_residue * 0.3;
            if (post_residual - next_item_size) == 0 {
                score -= 40.0; // chain of perfect fits
            }
        } else {
            score += 12.0; // next item won't fit here; mild penalty
            if post_residual < 20 {
                score += 15.0; // residual too small for typical next item
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer filling bins when many bins are open (reduce bin proliferation)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64) * 0.15 * (1.0 - progress);

    // Tie toward bins whose residual is below the mean (consolidate emptier space)
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.05;

    // New-bin candidate: only attractive when current residual is awkward
    if bin_residual == bin_capacity {
        let awkward = post_residual as f64; // for empty bin, post_residual == capacity - item
        if awkward > 55.0 || (next_item_size > 0 && next_item_size > awkward) {
            score -= 8.0; // fresh bin is fine for big items
        } else {
            score += 45.0; // discourage opening new bins for easy fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space avoidance: gap is dead only if smaller than the next item (or tiny)
    let next = next_item_size as f64;
    if post == 0.0 {
        score -= 1000.0;
    } else {
        let reusable_floor = if next > 0.0 && next <= post { next } else { 1.0 };
        let deadness = if post < 20.0 {
            3.0 - post / 20.0
        } else {
            1.0
        };
        // extra penalty proportional to how much of the gap is truly stranded
        let stranded = post - (reusable_floor - 1.0).min(post);
        score += stranded * (deadness - 1.0) * 2.5;
    }

    // Tightness reward, sharpened with a quadratic term for near-perfect fits
    let tightness = 1.0 - post / cap;
    score -= tightness * 15.0 + tightness * tightness * 10.0;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: open only when open bins are poor fits or the stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fits_next = next > 0.0 && next <= bin_capacity as f64;
        let lookahead_bonus = if fits_next { 12.0 } else { 0.0 };
        // gate on mean residual: if open bins are mostly full, new bin is cheaper
        let mean_pressure = (mean_residual / cap).max(0.0) * 20.0;
        score += 65.0 + open_bins_count as f64 * 4.0 - progress * 12.0
            - lookahead_bonus - mean_pressure;
    }

    // Open-bin pressure: consolidation scales with how full open bins are
    score += open_bins_count as f64 * 0.5;

    // Lookahead: exact next-item fit is golden; near fit gets partial credit
    if next > 0.0 {
        if (next_item_size as u32) == post_residual {
            score -= 35.0;
        } else if next <= post {
            score -= 5.0;
        } else {
            score += 5.0;
        }
    }

    // Mean-residual coupling with non-linear damping near the mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += if dev < 10.0 { dev * 0.05 } else { dev * 0.15 - 1.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

