    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual < next_item_size {
            // Dead space relative to the next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.35;
        } else {
            // Next item fits comfortably in leftover: mild reward.
            score -= 5.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits, or when existing residuals are highly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 55.0
            + open_bins_count as f64 * 3.0
            - fragmentation * 35.0
            - (fitting_bins_count == 0) as i32 as f64 * 120.0
            - progress * 15.0;
    } else {
        // Prefer filling already-open bins with large residual (reduce fragmentation).
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill_ratio * 18.0;

        // Mean-residual coupling: prefer bins near the mean residual.
        score += ((bin_residual as f64) - mean_residual).abs() * 0.12;

        // Mild penalty for spreading across many open bins when mean residual is low.
        if (item_size as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 0.4;

    // Late-stream consolidation: as the stream progresses, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - item_size as f64).max(0.0) * 0.12;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
