        let strand = if next_fits { 0.0 } else { 4.0 };
        score += post * (deadness - 1.0) * 2.0 + strand;
    }

    // Tightness reward, slightly stronger than parent to push compact fills
    let tightness = 1.0 - post / cap;
    score -= tightness * 18.0;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate decision: open a new bin only when open bins are poor fits
    // (post_residual much smaller than what a fresh bin would leave) or late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item = item_size as f64;
        // Waste of the best alternative: how much space would a fresh bin waste vs. existing bins
        let fresh_waste = cap - item;
        let lookahead_bonus = if next_item_size > 0 && (next_item_size as f64) <= cap - item {
            12.0
        } else {
            0.0
        };
        // If existing fitting bins leave tiny residuals, opening a new bin is wasteful;
        // if they leave large residuals (poor fits), opening is more attractive.
        let open_pressure = if fitting_bins_count > 0 {
            (mean_residual / cap).clamp(0.0, 1.0) * 20.0
        } else {
            0.0
        };
        score += 55.0 + open_bins_count as f64 * 4.0 - progress * 15.0
            - lookahead_bonus - open_pressure
            + (fresh_waste / cap) * 10.0;
    }

    // Consolidation pressure
    score += open_bins_count as f64 * 0.5;

    // Lookahead: exact fit for the next item in the leftover space
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // If the next item fits in bin_residual but not post_residual, this placement
        // blocks a good follow-up: penalize proportionally to how close it was.
        if (next_item_size as u32) <= bin_residual {
            score += 8.0 + (post / cap) * 10.0;
        } else {
            score += 5.0;
        }
    }

    // Mean-residual balancing, reduced weight so tight fits dominate
    score += ((bin_residual as f64) - mean_residual).abs() * 0.08;

    score
}

