        score -= 55.0;
    }

    // New-bin candidate gating. Opening a bin is only justified when:
    //  a) the current item fits the new bin better than any open bin, AND
    //  b) the leftover after placement still serves the next item (or stream end).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let next_fits_leftover = next_item_size > 0
            && (next_item_size as u32) <= post_residual
            && post_residual > 0;
        let mut new_bin_penalty = 55.0 + open_bins_count as f64 * 5.0 - progress * 15.0;
        if next_fits_leftover {
