    score += open_bins_count as f64 * 0.6;

    // Lookahead on open bins: reward placements that leave a perfect slot for
    // the next item; penalize stranding a residual the next item cannot use.
    if next_item_size > 0 {
        let n = next_item_size as u32;
        if n == post_residual {
            score -= 45.0;
        } else if n > post_residual {
            // next item can't use this bin's leftover — mild stranding penalty,
            // but only if the leftover is small enough to be worthless.
            if post_residual < 15 {
                score += 8.0;
            } else {
