    score -= tightness * 20.0;

    // Exact-fit lookahead: next item perfectly fills the leftover -> very strong reward
    if next_item_size > 0 {
        let nxt = next_item_size as u32;
        if nxt == post_residual {
            score -= 60.0;
        } else if nxt < post_residual {
            // next item fits here later; reward leaving just enough room
            score -= 10.0;
            let leftover_after_next = post_residual - nxt;
            if leftover_after_next < min_plausible as u32 {
                score -= 15.0; // chain-fill: this placement sets up a near-perfect pair
            }
        } else {
            // next item can't use this residual: penalize stranding proportional to waste
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    } else if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 15.0; // mild consolidation pressure when few options exist
    }

    // New-bin candidate: open only when no open bin offers a decent fit
    // and the stream still has plenty of items to justify fresh capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let next_fits_current = next_item_size > 0 && (next_item_size as u32) <= bin_residual;
        // base cost of a new bin; cheaper early (long future to amortize), expensive late
        let mut new_bin_cost = 45.0 + open_bins_count as f64 * 5.0 - progress * 15.0;
        if next_fits_current {
            // if the next item could fit an untouched bin, opening now is less wasteful
            new_bin_cost -= 12.0;
        }
        // if the current item leaves a stranded gap in any open bin, new bin is more attractive
        if post < min_plausible {
            new_bin_cost -= 25.0;
        }
        score += new_bin_cost;
    }

    // Consolidation pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.6;

    // Mean-residual coupling: keep the residual distribution compact and predictable
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    // Prefer bins whose residual is an even multiple relationship with typical items
    if mean_residual > 0.0 && (bin_residual as f64) % mean_residual.max(1.0) < 1.0 && bin_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
