    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fill_ratio = 1.0 - res / cap;
        score -= 35.0 + fill_ratio * 35.0;
    }

    // New-bin candidate: open only when item is large or many bins already open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_ratio = item / cap;
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= bin_residual as f64;
