pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual) with a non-linear penalty on waste.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_frac * waste_frac;

    // Reward filling bins more completely relative to the current item.
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this placement (perfect pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Partial compatibility: reward proportionally to how well next item nests.
            let nest = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * nest;
        } else {
            // Next item cannot use the leftover: mild penalty for stranded residual,
            // scaled by how dead the space is.
            let dead = post_residual as f64 / next_item_size as f64;
            score += 3.0 * (1.0 - (1.0 / (1.0 + dead)));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: late in the stream, prefer closing bins tightly (avoid many
    // half-empty bins at the end); early, be more exploratory.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (item_size as f64 / bin_capacity as f64);
    score += 4.0 * progress * waste_frac;

    // Global state: many open bins with high mean residual -> encourage consolidation
    // into fuller bins; a fresh empty bin candidate should be penalized in that case.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, modulated by global pressure.
        let mut new_bin_cost = 15.0;
        new_bin_cost += open_bins_count as f64 * 1.5;
        new_bin_cost += (mean_residual - (bin_capacity as f64 * 0.5)).max(0.0) * 0.2;
        // If the item is large relative to typical residuals, a new bin is more acceptable.
        new_bin_cost -= (item_size as f64 / bin_capacity as f64) * 10.0;
        // Last resort: no open bin fits.
        if fitting_bins_count == 0 {
            new_bin_cost -= 30.0;
        }
        score += new_bin_cost;
    } else {
        // Existing bin: slight preference for bins below mean residual (less-full bins
        // absorb the item, keeping tight bins tight for small future items) — but only
        // when the fit is good.
        if (post_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Small stochastic-free diversity term to break ties toward balanced residual spread.
    score += 0.01 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
