    if progress > 0.85 && post_residual > 0 && post_residual <= 10 {
        score += 8.0;
    }

    // Mid-stream harmonic tightening — penalize residuals that can
    // hold neither the next item nor a half-capacity block, nudging compaction
    if post_residual > 30 && next_item_size > 0 && next_item_size > post_residual {
        score += (post_residual % 10) as f64 * 0.6;
    }

    // MUTATION: waste-quantile shaping — residuals in the 21..29 band are the
    // classic "just missed a medium item" zone; steer away from them unless
    // the next item actually fits there
    if post_residual >= 21 && post_residual <= 29 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 4.5 - progress * 2.0;
        } else {
            score -= 3.0;
        }
    }

    score
}

