    // early on, prefer tight fits; late in stream, dead space matters more.
    let tightness = (1.0 - x) * (1.0 - x); // quadratic fit quality
    let progress_curve = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 12.0 * tightness * (0.5 + progress_curve);

    // Cubic interaction: exact fills (x ~ 0) get extra late-stream reward
    score -= 8.0 * (1.0 - x).powi(3) * (0.3 + progress_curve);

