        score -= 150.0; // perfect fill: strongly reward
    } else {
        // super-linear deadness shaping for tiny leftovers
        let deadness = if post < 22.0 { 3.2 - post / 22.0 } else { 1.0 };
        score += post * (deadness - 1.0) * 2.4;
        if post_residual % 20 == 0 {
            score -= 11.0; // clean fraction of capacity
        } else if post_residual % 10 == 0 {
            score -= 5.0; // semi-clean multiples of 10
        } else {
            score += residue_class * 0.4; // dead-space penalty scaled by residue
        }
        if post_residual <= 5 {
            score += 16.0; // nearly dead sliver
        } else if post_residual >= 6 && post_residual <= 15 {
            score += 5.0;
        } else if post_residual >= 16 && post_residual <= 19 {
            score += 3.0;
        }
    }

    // Tightness reward, capacity-normalized
    let tightness = 1.0 - post / cap;
    score -= tightness * 20.0;

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        if nd == post {
            score -= 42.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            let pair_residue = ((post_residual - next_item_size) % 20) as f64;
            score -= 10.0 - pair_residue * 0.3;
            if post_residual >= next_item_size * 2 {
                score -= 4.0;
            }
            if (post_residual - next_item_size) % 20 == 0 {
                score -= 6.0;
            }
        } else {
            score += 6.0;
            if post < 20.0 {
                score += 15.0;
            }
            // near-miss penalty: residual just barely too small
            if post_residual > 0 && post < 60.0 {
                let miss = nd - post;
                score += (10.0 - miss).max(0.0) * 0.8;
                if miss <= 10.0 {
                    score += 12.0;
                }
            }
        }
        // Two-item perfect chain reward
        if post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next == 0 {
                score -= 18.0;
            } else if after_next <= 5 {
                score += 7.0;
            }
        }
        // Triple-chain potential
        if post_residual >= next_item_size * 2 {
            let after_two = post_residual - next_item_size * 2;
            if after_two == 0 {
