            base -= 12.0;
        }
        if open_bins_count <= 2 {
            base -= 6.0;
        }
        if progress > 0.75 {
            base += 10.0;
        }
        score += base;
    }

    // Progress-aware tie-break
    score -= progress * 3.0;

    // Late-stream squeeze: exact residuals extra-rewarded near the end
    if progress > 0.7 && post_residual == 0 {
        score -= 8.0;
    }
    if progress > 0.85 && post_residual > 0 && post_residual <= 10 {
        score += 8.0;
    }

    // MUTATION: mid-stream harmonic tightening — penalize residuals that can
    // hold neither the next item nor a half-capacity block, nudging compaction
    if post_residual > 30 && next_item_size > 0 && next_item_size > post_residual {
        score += (post_residual % 10) as f64 * 0.6;
    }

    // MUTATION: awkward-midband squeeze — residuals in 21..29 rarely match
    // typical item sizes; discourage leaving them behind mid-stream
    if post_residual >= 21 && post_residual <= 29 && progress < 0.8 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
