    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - norm_pr));

    // Smooth polynomial coupling with stream progress: later in stream, punish waste harder
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Perfect-fit reward (smooth exponential decay rather than hard threshold)
    score -= 12.0 * (-pr / 6.0).exp();

    // Dead-space penalty: residual too small to be useful later (smooth falloff)
    let dead_zone = (-(pr - 10.0).abs() / 8.0).exp();
    score += 6.0 * dead_zone;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
