    score += 2.0 * (bin_residual as f64 - mean_residual) / cap;

    // Mild penalty for proliferating open bins early in stream
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate: neutral reference score, opened only when fits are poor
    if bin_residual == bin_capacity {
        score = 25.0 + 15.0 * progress + 0.3 * mean_residual;
    }

    score
}

