pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 40.0 * tight * tight;
    }

    // Penalize large post residuals that create dead space, especially small ones (< 10 unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: mild penalty if post_residual is large wasted space
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer filling an existing bin perfectly.
        score -= 200.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Many open bins: discourage spreading, prefer consolidating into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);
    }

    // Prefer bins whose residual is below the mean (fuller bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (post_residual as f64) < 0.35 * bin_capacity as f64;
        if bad_fit {
            score -= 50.0;
        } else {
            score += 120.0 + 30.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
