        }
        if progress > 0.75 {
            base += 10.0;
        }
        // MUTATION: refuse new bins when an open bin would leave a near-perfect
        // residue matching the next item's size (wasted-opportunity guard)
        if next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 8 && fitting_bins_count > 0 {
