}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize residuals too small to ever be useful (dead space)
        let min_possible = 1u32;
        if post_residual < min_possible * 10 {
            score += 30.0;
        }
        // Squared waste term: strongly discourage large leftovers
        score += (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else {
            // leftover wasted relative to lookahead
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: fill tightest bin
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Prefer tighter fits among many candidates
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(10.0);
    }

    // Time horizon: early in stream, be conservative (favor new bins / big leftovers);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 2 {
        score -= 0.8 * (open_bins_count.min(30) as f64) * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate calibration: empty bin has post_residual == capacity;
    // make it attractive only when the item is large or fit is otherwise poor.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score = post_residual as f64 - 10.0 * fill_frac;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    score
}

