    score += 0.3 * (r - mean_residual).abs();

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

