    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it's too small for the smallest plausible item (1..100 range,
    // but conservatively assume items >= 10 typical; small gaps < 10 are fully wasted).
    if post_residual < 10 {
        score += 25.0; // dead space penalty
    } else if post_residual <= 20 {
        score += 8.0; // risky gap
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next == 0 {
            score -= 30.0;
        } else if gap_after_next < 10 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin candidate more as open_bins_count grows).
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: empty bin residual == capacity. Discourage unless
    // no good fit exists (large post_residual would mean huge waste otherwise).
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    }

    // Mild preference for bins tighter than average (waste concentration).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Stream progression: late in stream, be slightly more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space shaping: super-linear penalty for tiny leftovers
    if post_residual == 0 {
        score -= 150.0; // perfect fill
    } else {
        let deadness = if post < 22.0 { 3.2 - post / 22.0 } else { 1.0 };
        score += post * (deadness - 1.0) * 2.4;
        if post_residual % 20 == 0 {
            score -= 11.0;
        }
        if post_residual % 10 == 0 && post_residual % 20 != 0 && post_residual >= 10 {
            score -= 5.0;
        }
        if post_residual <= 5 {
            score += 16.0;
        }
        if post_residual >= 6 && post_residual <= 15 {
            score += 5.0;
        }
        if post_residual >= 16 && post_residual <= 19 {
            score += 3.0;
        }
    }

    // Tightness reward, capacity-normalized
    let tightness = 1.0 - post / cap;
    score -= tightness * 20.0;

    // Last-chance bin: urgency scaled by fill level
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fill_ratio = 1.0 - res / cap;
        score -= 38.0 + fill_ratio * 27.0;
    }

    // New-bin candidate: penalize unless it enables a great future fit
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / cap;
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        let mut base = if size_ratio > 0.7 { 40.0 } else { 62.0 };
        base += open_bins_count as f64 * 4.0 - progress * 12.0;
        if next_fits {
            base -= 12.0;
        }
        if post_residual > 55.0 || (next_item_size > 0 && next_item_size > post_residual) {
            base -= 12.0;
        }
        if open_bins_count <= 2 {
            base -= 6.0;
        }
        if progress > 0.75 {
            base += 10.0;
        }
        score += base;
    }

    // Open-bin pressure: consolidate as bins proliferate
    score += open_bins_count as f64 * (0.35 + open_bins_count as f64 * 0.02);

    // Lookahead: chain-fitting with harmonic structure
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        if nd == post {
            score -= 42.0;
        } else if nd <= post {
            let pair_residue = ((post_residual - next_item_size) % 20) as f64;
            score -= 10.0 - pair_residue * 0.3;
            if post_residual >= next_item_size * 2 {
                score -= 4.0;
            }
            if (post_residual - next_item_size) % 20 == 0 {
                score -= 6.0;
            }
        } else {
            score += 6.0;
            if post < 20.0 {
                score += 15.0;
            }
        }
        if post_residual > 0 && post_residual < 60 && nd > post {
            let miss = nd - post;
            score += (10.0 - miss).max(0.0) * 0.8;
            if miss <= 10.0 {
                score += 12.0;
            }
        }
        if post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next == 0 {
                score -= 18.0;
            } else if after_next <= 5 {
                score += 7.0;
            }
        }
        if post_residual >= next_item_size * 2 {
            let after_two = post_residual - next_item_size * 2;
            if after_two == 0 {
                score -= 10.0;
            } else if after_two <= 5 {
                score += 4.0;
            }
        }
    }

    // Mean-residual coupling: mild balancing
    score += (res - mean_residual).abs() * 0.1;

    // Relative-fit term: prefer bins where item consumes a large fraction of residual
    let fit_ratio = item_size as f64 / res.max(1.0);
    score -= fit_ratio * 11.0;

    // Progress-aware tie-break
    score -= progress * 3.0;

    // Late-stream squeeze
    if progress > 0.7 && post_residual == 0 {
        score -= 8.0;
    }
    if progress > 0.85 && post_residual > 0 && post_residual <= 10 {
        score += 8.0;
    }

    // MUTATION 1: mid-stream harmonic tightening, extended to awkward bands
    if post_residual > 30 && next_item_size > 0 && next_item_size > post_residual {
        score += (post_residual % 10) as f64 * 0.6;
    }

    // MUTATION 2: exact-fit lookahead on the item itself — reward bins where the
    // item lands the residual on a harmonic multiple of 10 (flexible leftovers)
    if bin_residual >= item_size && bin_residual != bin_capacity {
        let r = bin_residual - item_size;
        if r % 10 == 0 && r > 0 {
            score -= 4.0;
        }
        // prefer bins where item nearly exhausts residual (best-fit pressure)
        if r <= 3 {
            score -= 6.0;
        }
    }

    // MUTATION 3: two-item lookahead gap — if next item misses post_residual by a
    // tiny margin, penalize lightly so near-fitting bins stay competitive
    if next_item_size > post_residual && post_residual > 0 {
        let gap = next_item_size - post_residual;
        if gap <= 3 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Near match: next item fits in the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward tighter matches (less slack left after the lookahead item).
        let slack_after_lookahead = (post_residual - next_item_size) as f64;
        score -= 10.0 + 8.0 * (1.0 - slack_after_lookahead / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Lookahead cannot use the residual: penalize dead space more strongly.
        score += 6.0;
    }

    // Penalize residuals that are too small to ever be useful (below min item size 1..100 range).
    if post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 100.0 } else { 0.0 };
        let mean_r = mean_residual.max(0.0);
        // Prefer new bin only if existing residuals are very tight relative to item.
        score += 30.0 + urgency - mean_r * 0.2;
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 5.0; // new bin can also host the lookahead item
        }
    }

    // Progress-based mild tightening: later in stream, prefer tighter fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Coupling with mean residual: bins tighter than mean are more valuable to fill.
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

