pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly prefer minimal post-residual (best-fit core).
    score += 0.6 * (post_residual as f64 / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Penalize placing into bins whose residual far exceeds the item (wasteful harvest).
    let slack_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * slack_ratio * slack_ratio;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Many fitting bins -> keep tightest ones for the item, prefer bins with small residual.
    if fitting_bins_count > 1 {
        score += 2.5 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * chain_fit;
        } else {
            // Next item won't fit here; slightly penalize leaving awkward gaps.
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score += 0.08 * gap;
        }
    }

    // Dead-space penalty for very small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate handling: only attractive late in stream or when open bins fit poorly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin: base cost so it's chosen only when genuinely better.
        score += 15.0 + 25.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
        // Favor new bin when open bins are nearly full on average.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 20.0;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild time-varying exploration: early stream, prefer consolidating into few bins.
    score += (1.0 - progress) * 0.05 * open_bins_count as f64;

    // Prefer bins whose residual is close to mean (stability) with slight nonlinearity.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * dev * dev * (1.0 - progress);

    score
}

