        }
        score += base;
    }

    // Open-bin pressure
    score += open_bins_count as f64 * (0.4 + open_bins_count as f64 * 0.02);

    // Lookahead: chain-fitting with harmonic structure
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        if nd == post {
            score -= 45.0;
        } else if nd <= post {
            let after = post_residual - next_item_size;
            let pair_residue = (after % 20) as f64;
            score -= 10.0 - pair_residue * 0.3;
            if post_residual >= next_item_size * 2 {
                score -= 4.0;
            }
            if after % 20 == 0 {
                score -= 6.0;
            }
            if after == 0 {
                score -= 18.0;
            } else if after <= 5 {
                score += 7.0;
            }
            if post_residual >= next_item_size * 2 {
                let after_two = post_residual - next_item_size * 2;
