}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Normalized post-residual (dead space fraction)
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early in stream: prefer leaving large residuals (flexibility) -> mild penalty on small pr.
    // Late in stream: consolidate aggressively -> strong penalty on large pr.
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) + norm_pr * (0.5 + 2.0 * progress * progress);

    let mut score = pr + 2.0 * poly * cap;

    // Smooth tightness reward: reward small residuals with a saturating term
    let tight = (1.0 - norm_pr).powi(3);
    score -= 4.0 * tight * (1.0 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 25.0 * progress;
    }

    // New-bin candidate: penalize smoothly, but relax when it would leave a
    // residual well-matched to the next item (smooth lookahead coupling).
    if is_new_bin {
        let next_fit = if next_item_size > 0 {
            (pr - next_item_size as f64).abs() / cap
        } else {
            1.0
        };
        let lookahead_bonus = (1.0 - next_fit.min(1.0)).powi(2);
        score += 18.0 + 12.0 * progress - 20.0 * lookahead_bonus;
    } else {
        // Smooth bonus if remaining residual still fits the next item
        if next_item_size > 0 && (pr as u32) >= next_item_size {
            score -= 3.0 + 3.0 * (1.0 - (pr - next_item_size as f64) / cap);
        }
    }

    // Mild penalty for proliferating bins relative to stream length
    score += (open_bins_count as f64) * (0.5 * progress);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 0.5 * (pr - mean_residual).abs() / cap;

    score
}

