    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 + 2.0 * progress) - prn * prn * prn * (1.5 + progress);

    let mut score = pr * (1.0 + poly);

    // Reward tight fits more as stream progresses (smooth ramp)
    score -= it * fill * fill * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        let unusable = if pr < next_item_size as f64 { pr } else { 0.0 };
        score += unusable * (0.8 + 0.4 * progress);
        score -= gap * 0.1 * (1.0 - progress);
    } else {
        score += pr * 0.3 * progress;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild coupling with global residual state
    score += (mean_residual - pr) * 0.05;
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space shaping: super-linear penalty for tiny leftovers
    if post_residual == 0 {
        score -= 155.0;
    } else {
        let deadness = if post < 22.0 { 3.2 - post / 22.0 } else { 1.0 };
        score += post * (deadness - 1.0) * 2.4;
        if post_residual % 20 == 0 {
            score -= 11.0;
        } else if post_residual % 10 == 0 && post_residual >= 10 {
            score -= 5.0;
        }
        if post_residual <= 5 {
            score += 16.0;
        } else if post_residual <= 15 {
            score += 5.0;
        } else if post_residual <= 19 {
            score += 3.0;
        }
    }

    // Tightness reward, capacity-normalized
    let tightness = 1.0 - post / cap;
    score -= tightness * 20.0;

    // Last-chance bin urgency scaled by fill level
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fill_ratio = 1.0 - res / cap;
        score -= 38.0 + fill_ratio * 28.0;
    }

    // New-bin candidate: open only when consolidation is hopeless or it unlocks a great fit
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / cap;
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        let mut base = if size_ratio > 0.7 { 38.0 } else { 62.0 };
        base += open_bins_count as f64 * 4.0 - progress * 12.0;
        if next_fits {
            base -= 12.0;
        }
        if post_residual > 55.0 || (next_item_size > 0 && next_item_size > post_residual) {
            base -= 12.0;
        }
        if open_bins_count <= 2 {
            base -= 6.0;
        }
        if progress > 0.75 {
            base += 10.0;
        }
        score += base;
    }

    // Open-bin pressure
    score += open_bins_count as f64 * (0.35 + open_bins_count as f64 * 0.02);

    // Lookahead: chain-fitting with harmonic structure
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        if nd == post {
            score -= 44.0;
        } else if nd <= post {
            let after = post_residual - next_item_size;
            let pair_residue = (after % 20) as f64;
            score -= 10.0 - pair_residue * 0.3;
            if post_residual >= next_item_size * 2 {
                score -= 4.0;
            }
            if after % 20 == 0 {
                score -= 6.0;
            }
            if after == 0 {
                score -= 18.0;
            } else if after <= 5 {
                score += 7.0;
            }
            if post_residual >= next_item_size * 2 {
                let after_two = post_residual - next_item_size * 2;
                if after_two == 0 {
                    score -= 10.0;
                } else if after_two <= 5 {
                    score += 4.0;
                }
            }
        } else {
            score += 6.0;
            if post < 20.0 {
                score += 15.0;
            }
            if post_residual > 0 && post_residual < 60 {
                let miss = nd - post;
                score += (10.0 - miss).max(0.0) * 0.8;
                if miss <= 10.0 {
                    score += 12.0;
                }
            }
        }
    }

    // Mean-residual coupling: mild balancing
    score += (res - mean_residual).abs() * 0.1;

    // Relative-fit term
    let fit_ratio = item_size as f64 / res.max(1.0);
    score -= fit_ratio * 11.0;

    // Progress-aware tie-break
    score -= progress * 3.0;

    // Late-stream squeeze
    if progress > 0.7 && post_residual == 0 {
        score -= 8.0;
    }
    if progress > 0.85 && post_residual > 0 && post_residual <= 10 {
        score += 8.0;
    }

    // MUTATION: mid-stream harmonic tightening — penalize off-harmonic residuals
    // that can't hold the next item, but reward those matching half-capacity blocks
    if post_residual > 30 && next_item_size > 0 && next_item_size > post_residual {
        score += (post_residual % 10) as f64 * 0.6;
    }
    if post_residual > 40 && post_residual % 50 == 0 {
        score -= 4.0;
    }

    // MUTATION: residual-variance dampening — prefer bins near the mean residual
    // when the item fits loosely, to keep the residual distribution compact
    if (item_size as f64) < res * 0.5 {
        score += (res - mean_residual).abs() * 0.05;
    }

    score
}

