    if post_residual >= 8 && post_residual % 8 == 0 {
        score -= 4.0;
    }
    if post_residual >= 12 && post_residual % 12 == 0 {
        score -= 3.0;
    }

    // MUTATION gen 27: anti-fragmentation — when many bins are open, prefer
    // placements that fully consume the residual (exact or near-exact fits),
    // tightening overall compaction under high bin proliferation.
    if open_bins_count > 5 && post_residual > 0 && post_residual <= item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (0..=10) are nearly perfect; reward them.
    let post = post_residual;
    let residue_class = post % 25; // harmonic quarter-classes of capacity
    if post == 0 {
        score -= 60.0; // perfect closure
    } else if post <= 10 {
        score -= 25.0;
    } else if residue_class == 0 {
        score -= 8.0; // exact quarter/half/three-quarter fill: reusable class
    }

    // Dead-space penalty: post_residual that no plausible next item (1..=100)
    // can use well. If post_residual < smallest useful next chunk, penalize.
    if post > 0 && post < 10 {
        score += 30.0; // sliver of unusable space
    }

    // Coupling with lookahead: if the next item fits exactly into the
    // post residual, strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0;
        } else if next_item_size < post {
            let slack = post - next_item_size;
            if slack <= 10 {
                score -= 12.0;
            } else {
                score += slack as f64 * 0.3; // next item would leave big gap here
            }
        } else {
            // next item cannot follow here; mild penalty scaled by overflow
            score += (next_item_size - post).min(30) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + (bin_residual - item_size).min(40) as f64 * 0.2;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer reusing open bins when any decent fit exists; new bin is a
        // fallback. Base score high, discounted when many bins are open and
        // mean residual is large (fragmentation already high).
        score = 55.0
            + (post_residual as f64) * 0.5
            - (open_bins_count as f64).min(20.0) * 0.4
            - mean_residual.min(80.0) * 0.25;
        // Early in the stream, opening bins is cheap and useful.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
        // If item is large relative to capacity, a fresh bin is natural.
        if item_size * 2 >= bin_capacity {
            score -= 10.0;
        }
    }

    // Tie-break toward fuller bins overall: prefer bins with smaller residual
    // relative to the mean (best-fit flavor with harmonic scaling).
    let frac = bin_residual as f64 / bin_capacity as f64;
    score += frac * frac * 10.0;
    score -= (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.05;

    score
}

