pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: worst outcome, huge penalty.
            score += 60.0 * (10.0 - post_residual as f64);
        } else {
            // Usable leftover: mild quadratic penalty to prefer tighter fits.
            score += 0.08 * (post_residual as f64).powi(2);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward when the leftover can exactly host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Leftover still usable by next item: small bonus proportional to slack.
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that are already fairly full.
        let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 15.0 * fill_ratio;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; keep scores
    // of existing bins lower than a fresh empty bin unless fit is poor.
    let bin_pressure = open_bins_count as f64 * 0.6;
    if bin_residual != bin_capacity {
        score -= bin_pressure.min(12.0);
    } else {
        // New empty bin: baseline cost plus pressure so it's chosen only when
        // existing fits create dead space.
        score += 20.0 + bin_pressure.min(12.0);
    }

    // Early in the stream, opening bins is cheaper; late, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Mean-residual coupling: if this bin's residual deviates favorably (low residual
    // = full bin), reward slightly.
    score -= (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.15;

