        let fill = next_item_size as f64 / cap;
        score -= 10.0 * fill * (1.0 - norm_pr) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 / cap) * norm_pr;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - norm_pr);
