            if post_residual >= next_item_size * 2 {
                score -= 4.0;
            }
            if (post_residual - next_item_size) % 20 == 0 {
                score -= 6.0;
            }
        } else {
            score += 6.0;
            if pr < 20.0 {
                score += 15.0;
            }
        }
        if pr > 0.0 && pr < 60.0 && nd > pr {
