        score += 5.0 * norm_post;
    }

    // Coupling with mean residual: prefer bins whose residual is below mean
    // (tighter bins get priority), smooth cubic in the difference
    let diff = mean_residual - post;
    score -= 0.15 * diff * (1.0 + diff * diff / (cap * cap));

    // Prefer fewer open bins mildly (consolidation), weighted by progress
    score += 0.3 * open_bins_count as f64 * (0.5 + 0.5 * progress);

