pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well the leftover space partitions
    // the capacity into "nice" modular classes (small leftovers are good).
    let cap = bin_capacity as f64;

    // Class A: near-perfect fit (post_residual in tiny band) -> strong reward
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 12 {
        score -= 25.0;
    } else if post_residual <= 25 {
        score -= 8.0;
    }

    // Integer-division harmonic classes: post_residual / 10 buckets.
    // Leftovers in mid-range classes (30-60) are "dead zone" -> penalize.
    let class = post_residual / 10;
    match class {
        0 => score -= 15.0,
        1 => score -= 5.0,
        2 => score += 3.0,
        3 => score += 10.0,
        4 => score += 14.0,
        5 => score += 10.0,
        6 => score -= 2.0,
        7 => score -= 6.0,
        8 => score -= 10.0,
        _ => {}
    }

    // Modulo coupling: post_residual % 10 — leftovers that align with common
    // item sizes (multiples of 10) are reusable; odd remainders penalized.
    let rem = post_residual % 10;
    score += rem as f64 * 0.8;

    // Lookahead: if next item fits into post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
