    // for stranding a bin that could have held the next item elsewhere.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor it
