    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog_curve = progress * (1.0 - progress) * 4.0; // peaks mid-stream

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: small post_residual (< ~20) is usually unusable later.
    let pr = post_residual as f64;
    let dead = (1.0 - (pr / 30.0)).max(0.0);
    score += 12.0 * dead * dead;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * prog_curve;
    }

    // New-bin candidate: penalize opening a bin unless the item is large relative
    // to capacity or the current mean residual is very fragmented.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / bin_capacity as f64;
        let fragmentation = (mean_residual / bin_capacity as f64 - 0.5).abs();
        score += 18.0
            - 25.0 * size_ratio * size_ratio
            + 20.0 * fragmentation
            + 10.0 * (1.0 - prog_curve);
