            score -= 25.0; // next item plugs the sliver exactly
        } else {
            score += 15.0; // dead sliver, penalize
        }
    } else if frac <= 0.25 {
        score -= 12.0;
    } else if frac <= 0.5 {
        score -= 6.0;
    } else if frac <= 0.75 {
        score += 2.0;
    }

    // Modulo classes on post_residual: residues that match common item sizes
    // are more likely to be filled by a future item.
    let r = post_residual % 10;
    if r == 0 {
        score -= 5.0; // round residual, divisible by common size quantum
    } else if r >= 5 {
        score += 1.5;
    }

