pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are toxic.
    // Items are >= 1, but typical useful gaps are larger; treat very small gaps as dead.
    let dead_threshold: u32 = 9;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64; // unusable sliver
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit: zero waste is ideal
    }

    // Penalize gaps that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
        score -= 5.0; // gap exactly useful for the next item
    }

    // Reward tight fits relative to bin capacity (small waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_ratio * waste_ratio;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: prefer bins deviating below mean residual (fill fuller bins first).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline, slightly penalized so we only open
    // a new bin when open bins would create severe dead space.
    if bin_residual == bin_capacity {
