        let mut base = if size_ratio > 0.7 { 38.0 } else { 63.0 };
        base += open_bins_count as f64 * 4.0 - progress * 12.0;
        if next_fits {
            base -= 12.0;
        }
        if post_residual > 55.0 || (next_item_size > 0 && next_item_size > post_residual) {
            base -= 13.0;
        }
        if open_bins_count <= 2 {
            base -= 7.0;
        }
        if progress > 0.75 {
            base += 10.0;
        }
        score += base;
    }

    // Open-bin pressure: consolidate as bins proliferate
    score += open_bins_count as f64 * (0.35 + open_bins_count as f64 * 0.02);

    // Lookahead: chain-fitting with harmonic structure
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        if nd == post {
            score -= 44.0;
        } else if nd <= post {
            let pair_residue = ((post_residual - next_item_size) % 20) as f64;
            score -= 10.0 - pair_residue * 0.3;
            if post_residual >= next_item_size * 2 {
                score -= 4.0;
            }
            if (post_residual - next_item_size) % 20 == 0 {
                score -= 6.0;
            }
        } else {
            score += 6.0;
            if post < 20.0 {
                score += 15.0;
            }
        }
        if post_residual > 0 && post_residual < 60 && nd > post {
            let miss = nd - post;
            score += (10.0 - miss).max(0.0) * 0.8;
            if miss <= 10.0 {
                score += 12.0;
            }
        }
        // Two-item perfect chain reward
        if post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next == 0 {
                score -= 18.0;
            } else if after_next <= 5 {
                score += 7.0;
            }
        }
        // Triple-chain potential
        if post_residual >= next_item_size * 2 {
            let after_two = post_residual - next_item_size * 2;
            if after_two == 0 {
                score -= 10.0;
            } else if after_two <= 5 {
                score += 4.0;
            }
        }
    }

    // Mean-residual coupling: mild balancing
    score += (res - mean_residual).abs() * 0.1;

    // Relative-fit term: prefer bins where item consumes a large fraction of residual
    let fit_ratio = item_size as f64 / res.max(1.0);
    score -= fit_ratio * 12.0;

    // Progress-aware tie-break
    score -= progress * 3.0;

    // Late-stream squeeze: exact residuals extra-rewarded near the end
    if progress > 0.7 && post_residual == 0 {
        score -= 9.0;
    }
    if progress > 0.85 && post_residual > 0 && post_residual <= 10 {
        score += 8.0;
    }

    // Mid-stream harmonic tightening: penalize residuals that can't hold
    // the next item and are off-harmonic, nudging compaction
    if post_residual > 30 && next_item_size > 0 && next_item_size > post_residual {
        score += (post_residual % 10) as f64 * 0.7;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: penalize large post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 40.0;

    // Reward near-perfect packing (post_residual small relative to capacity).
    let pr = post_residual as f64;
    if pr <= 5.0 {
        score -= 30.0;
    } else if pr > 30.0 {
        score += (pr - 30.0) * 0.8; // dead-space penalty for large leftovers
    }

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            // penalize leaving a residual just barely too small for next item
            let gap = next_item_size as f64 - pr;
            if gap < 15.0 {
                score += gap * 0.6;
            }
        }
    } else {
        // Last item: prefer filling existing bins as much as possible.
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded && open_bins_count > 0 {
            score -= 10.0 + 20.0 * progress; // sometimes fresh bin is better
        } else {
            score += 45.0; // discourage wasting a new bin on a loose fit
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into bins with residual close to item size.
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += residual_gap * 0.3 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // later, pack aggressively into tight residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - bin_residual as f64) * 0.15;

    // Mild preference for bins with residual below mean (concentrate waste).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

