    // capacity-fraction buckets. Small post_residual classes are good (tight fit),
    // large ones are dead space.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward tight fits: post_residual in the lowest classes.
    if post_residual <= eighth {
        score -= 12.0;
    } else if post_residual <= quarter {
        score -= 5.0;
    } else if post_residual < bin_capacity / 2 {
        score += 3.0;
    } else {
        score += 10.0; // huge leftover = wasted bin space
    }

    // Modulo harmonic: leftover divisible by common item sizes (10/20/25) is
    // reusable by future items, so reward it.
    if post_residual != 0 && (post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0) {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves another leftover: mild reward scaled
            // by how well the pair packs.
            let pair_left = post_residual - next_item_size;
            score -= 8.0 * (1.0 - pair_left as f64 / cap);
        } else {
            // next item cannot use this leftover: penalize proportionally.
            score += 4.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate: only attractive when item is huge relative to typical
    // residuals or all fits are terrible. Penalize mildly by default.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.05 * open_bins_count as f64;
        // But if the item is large (>3/4 capacity), a fresh bin is often best.
        if item_size * 4 > bin_capacity * 3 {
            score -= 14.0;
        }
        // Early stream: opening bins is cheap and flexible.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 3.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (below mean
    // residual means this bin is already tight; keep filling tight bins).
    score += 0.15 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

