    score += 0.02 * bin_residual as f64;

    // Progression: late in the stream, consolidation matters more.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 2.0 * progress * post_f / cap;
    }

    score
}

