    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let pair_waste = post_residual - next_item_size;
            score -= 15.0 * (1.0 - pair_waste as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.15 * overshoot;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, prefer keeping bins flexible (favor
    // larger post_residual); late in the stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.10 * post_residual as f64;
    score -= progress * 10.0 * tightness;

