pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are "nice" fractions
    // of capacity (e.g. 0, 10, 20, 25, 50) are more likely to be filled later.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Reward exact zero waste strongly.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Reward post_residuals divisible by common item-size classes (10, 20, 25, 50)
        let div_reward: f64 = if pr % 10 == 0 { 12.0 } else { 0.0 }
            + if pr % 25 == 0 { 8.0 } else { 0.0 }
            + if pr % 50 == 0 { 6.0 } else { 0.0 };
        score -= div_reward;

        // Penalize small dead space (< 10) that nothing can ever use.
        if pr < 10 {
            score += 40.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            // reward proportionally, with harmonic preference for clean splits
            let fit_frac = next_item_size as f64 / prf;
            score -= 60.0 * fit_frac;
            if pr % next_item_size == 0 {
                score -= 25.0;
            }
        } else {
            // next item cannot follow into this bin: mild penalty unless bin is nearly full
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post residual would be tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
        if pr >= 10 {
            score -= 20.0;
        }
    }

    // New-bin candidate: penalize opening a new bin when good fits exist,
    // but allow it when open bins are crowded (mean residual low).
    if bin_residual == bin_capacity {
        score += 15.0;
        let pressure = mean_residual / cap;
        score += 60.0 * (1.0 - pressure.min(1.0));
    }

    // Prefer tighter bins overall: closeness of fill to capacity.
    let fill = (bin_residual as f64) / cap;
    score -= 30.0 * fill * fill;

    // Late in the stream, consolidate: discourage spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 3 {
        score += 5.0 * (open_bins_count as f64).ln() * (0.5 + 0.5 * progress);
    }

    score
}

