            }
        } else {
            score += 6.0;
            if pr < 20.0 {
                score += 14.0;
            }
            if pr > 0.0 {
                let miss = nd - pr;
                if miss <= 10.0 {
                    score += 10.0;
                }
            }
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fill_ratio = 1.0 - res / cap;
        score -= 30.0 + fill_ratio * 25.0 + 10.0 * progress;
    }

