        }
        if open_bins_count <= 2 {
            base -= 6.0;
        }
        if progress > 0.75 {
            base += 8.0;
        }
        score += base;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good, amplify it.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Reward near-exact fills (post_residual close to 0 is exponentially better).
    score -= 60.0 * (-post_residual as f64 / 12.0).exp();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize leaving dead space that likely cannot host the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // Reward residuals that can still accommodate the lookahead item.
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 55.0 + 40.0 * (1.0 - progress) + 60.0 * pressure;
        // Relax penalty if the item barely fits anywhere (large item, few fitting bins).
        let relief = if fitting_bins_count <= 1 { 30.0 } else { 0.0 };
        // If mean residual is small, open bins are nearly full; new bin is fine.
        let relief2 = (mean_residual / bin_capacity as f64).min(0.5) * 40.0;
        score += new_bin_penalty - relief - relief2;
    } else {
        // Mild preference for bins whose residual deviates from the mean
        // (consolidate into fuller bins).
        score += 0.15 * (bin_residual as f64 - mean_residual).abs();
